import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  toolbarButtonClassName,
  toolbarGroupClassName,
  toolbarInputClassName,
  toolbarLinkClassName,
  toolbarRootClassName,
  toolbarSeparatorClassName,
} from "./view";

export {
  toolbarButtonClassName,
  toolbarGroupClassName,
  toolbarInputClassName,
  toolbarLinkClassName,
  toolbarRootClassName,
  toolbarSeparatorClassName,
} from "./view";

export type ToolbarOrientation = "horizontal" | "vertical";
export type ToolbarStyle = Readonly<Record<string, string>>;

export type RootViewConfig = Readonly<{
  children: readonly Html[];
  ariaLabel?: string | undefined;
  orientation?: ToolbarOrientation | undefined;
  disabled?: boolean | undefined;
  className?: string | undefined;
  style?: ToolbarStyle | undefined;
}>;

export type GroupViewConfig = Readonly<{
  children: readonly Html[];
  ariaLabel?: string | undefined;
  orientation?: ToolbarOrientation | undefined;
  className?: string | undefined;
  style?: ToolbarStyle | undefined;
}>;

export type ButtonViewConfig<ParentMessage> = Readonly<{
  children: readonly Html[];
  ariaLabel?: string | undefined;
  onClick?: ParentMessage | undefined;
  orientation?: ToolbarOrientation | undefined;
  disabled?: boolean | undefined;
  focusableWhenDisabled?: boolean | undefined;
  className?: string | undefined;
  style?: ToolbarStyle | undefined;
}>;

export type LinkViewConfig = Readonly<{
  href: string;
  children: readonly Html[];
  orientation?: ToolbarOrientation | undefined;
  className?: string | undefined;
  style?: ToolbarStyle | undefined;
}>;

export type InputViewConfig<ParentMessage> = Readonly<{
  value: string;
  onInput: (value: string) => ParentMessage;
  ariaLabel: string;
  orientation?: ToolbarOrientation | undefined;
  disabled?: boolean | undefined;
  className?: string | undefined;
  style?: ToolbarStyle | undefined;
}>;

export type SeparatorViewConfig = Readonly<{
  orientation?: ToolbarOrientation | undefined;
  className?: string | undefined;
  style?: ToolbarStyle | undefined;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const stateAttributes = <ParentMessage>(
  h: ReturnType<typeof html<ParentMessage>>,
  orientation: ToolbarOrientation,
  disabled: boolean,
  focusableWhenDisabled = true
) => [
  h.DataAttribute("orientation", orientation),
  ...(disabled ? [h.DataAttribute("disabled", "")] : []),
  ...(disabled && focusableWhenDisabled
    ? [h.DataAttribute("focusable", "")]
    : []),
];

export const rootView = <ParentMessage>({
  children,
  ariaLabel,
  orientation = "horizontal",
  disabled = false,
  className,
  style,
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "toolbar"),
      ...(ariaLabel === undefined ? [] : [h.AriaLabel(ariaLabel)]),
      ...stateAttributes(h, orientation, disabled),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(toolbarRootClassName, className)),
    ],
    children
  );
};

export const groupView = <ParentMessage>({
  children,
  ariaLabel,
  orientation = "horizontal",
  className,
  style,
}: GroupViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "group"),
      ...(ariaLabel === undefined ? [] : [h.AriaLabel(ariaLabel)]),
      h.DataAttribute("orientation", orientation),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(toolbarGroupClassName, className)),
    ],
    children
  );
};

export const buttonView = <ParentMessage>({
  children,
  ariaLabel,
  onClick,
  orientation = "horizontal",
  disabled = false,
  focusableWhenDisabled = true,
  className,
  style,
}: ButtonViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      ...(ariaLabel === undefined ? [] : [h.AriaLabel(ariaLabel)]),
      ...stateAttributes(h, orientation, disabled, focusableWhenDisabled),
      ...(disabled ? [h.Disabled(true)] : []),
      ...(disabled || onClick === undefined ? [] : [h.OnClick(onClick)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(toolbarButtonClassName, className)),
    ],
    children
  );
};

export const linkView = <ParentMessage>({
  href,
  children,
  orientation = "horizontal",
  className,
  style,
}: LinkViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.a(
    [
      h.Href(href),
      h.DataAttribute("orientation", orientation),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(toolbarLinkClassName, className)),
    ],
    children
  );
};

export const inputView = <ParentMessage>({
  value,
  onInput,
  ariaLabel,
  orientation = "horizontal",
  disabled = false,
  className,
  style,
}: InputViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.input([
    h.Type("text"),
    h.Value(value),
    h.AriaLabel(ariaLabel),
    h.OnChange(onInput),
    h.OnInput(onInput),
    ...stateAttributes(h, orientation, disabled),
    ...(disabled ? [h.Disabled(true)] : []),
    ...(style === undefined ? [] : [h.Style(style)]),
    h.Class(classNames(toolbarInputClassName, className)),
  ]);
};

export const separatorView = <ParentMessage>({
  orientation = "vertical",
  className,
  style,
}: SeparatorViewConfig = {}): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "separator"),
      h.Attribute("aria-orientation", orientation),
      h.DataAttribute("orientation", orientation),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(toolbarSeparatorClassName, className)),
    ],
    []
  );
};

export const toolbarRootClassName =
  "inline-flex max-w-full items-center gap-1 overflow-x-auto rounded-lg border border-gray-200 bg-white p-1 shadow-sm";

export const toolbarGroupClassName = "inline-flex shrink-0 items-center gap-1";

export const toolbarButtonClassName =
  "inline-flex h-8 min-w-8 shrink-0 items-center justify-center whitespace-nowrap rounded-md px-2 text-sm font-medium text-gray-700 transition-colors hover:bg-gray-100 hover:text-gray-950 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const toolbarLinkClassName =
  "inline-flex h-8 shrink-0 items-center whitespace-nowrap rounded-md px-2 text-sm text-gray-500 transition-colors hover:bg-gray-100 hover:text-gray-950 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600";

export const toolbarInputClassName =
  "h-8 w-48 shrink-0 rounded-md border border-gray-200 bg-white px-2 text-sm text-gray-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const toolbarSeparatorClassName =
  "mx-1 h-5 w-px shrink-0 bg-gray-200 data-[orientation=vertical]:h-5 data-[orientation=vertical]:w-px data-[orientation=horizontal]:h-px data-[orientation=horizontal]:w-5";

import { Schema as S } from "effect";
import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { describe, expect, test } from "vitest";

import * as Toolbar from "./index";

const ClickedAlignLeft = m("ClickedAlignLeft");
const UpdatedFont = m("UpdatedFont", { value: S.String });
const Message = S.Union([ClickedAlignLeft, UpdatedFont]);
type Message = typeof Message.Type;

const view = (font: string): Html => {
  const h = html<Message>();

  return Toolbar.rootView<Message>({
    ariaLabel: "Editor toolbar",
    children: [
      Toolbar.groupView<Message>({
        ariaLabel: "Alignment",
        children: [
          Toolbar.buttonView<Message>({
            ariaLabel: "Align left",
            onClick: ClickedAlignLeft(),
            children: [h.span([], ["Align Left"])],
          }),
        ],
      }),
      Toolbar.separatorView<Message>(),
      Toolbar.inputView<Message>({
        ariaLabel: "Font family",
        value: font,
        onInput: (value) => UpdatedFont({ value }),
      }),
      Toolbar.linkView<Message>({
        href: "#edited",
        children: [h.span([], ["Edited 51m ago"])],
      }),
    ],
  });
};

describe("Toolbar registry view", () => {
  test("renders Base UI toolbar parts and routes interaction", () => {
    Scene.scene(
      {
        update: (model: string, message: Message): readonly [string, []] => {
          if (message._tag === "ClickedAlignLeft") {
            return [model, []];
          }
          expect(message._tag).toBe("UpdatedFont");
          return [message.value, []];
        },
        view,
      },
      Scene.with("Helvetica"),
      Scene.expect(Scene.role("toolbar", { name: "Editor toolbar" })).toExist(),
      Scene.expect(Scene.role("group", { name: "Alignment" })).toExist(),
      Scene.expect(Scene.role("button", { name: "Align left" })).toHaveAttr(
        "data-orientation",
        "horizontal"
      ),
      Scene.click(Scene.role("button", { name: "Align left" })),
      Scene.change(Scene.role("textbox", { name: "Font family" }), "Arial"),
      Scene.expect(Scene.role("textbox", { name: "Font family" })).toHaveValue(
        "Arial"
      ),
      Scene.expect(Scene.role("link", { name: "Edited 51m ago" })).toExist()
    );
  });
});
